"""Column conventions shared by every table: UUID primary keys and timezone-aware timestamps."""

import uuid
from datetime import datetime

from sqlalchemy import DateTime, Uuid, func, text
from sqlalchemy.orm import Mapped, mapped_column

from app.core import clock


class UUIDPrimaryKeyMixin:
    # Generated by PostgreSQL (gen_random_uuid, built in since PG 13) and by Python, so new
    # objects have an id before flush. Random UUIDs keep ids in URLs unguessable.
    id: Mapped[uuid.UUID] = mapped_column(
        Uuid, primary_key=True, default=uuid.uuid4, server_default=text("gen_random_uuid()")
    )


class CreatedAtMixin:
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=func.now()
    )


class TimestampMixin(CreatedAtMixin):
    # Maintained by the ORM on update (no trigger): raw SQL UPDATEs will not refresh it.
    updated_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        nullable=False,
        server_default=func.now(),
        onupdate=lambda: clock.now(),
    )
